export function opsText(lang:Language,key:string){return words[key]?label(words[key],lang):modules[key]?label(modules[key].title,lang):key;}
const customField=(key:string,title:Label,type='text',required=false,options?:string[]):Field=>({key,title,type,required,options});
const textField=(key:string,word:string,type='text',required=false,options?:string[])=>customField(key,words[word],type,required,options);
